    const area=`${line} L${x(points.length-1)},224 L${x(0)},224 Z`;
    const grid=[0,1,2,3].map(i=>{const yy=34+i*58, val=hi-(hi-lo)*i/3;return `<path d="M48 ${yy}H704" stroke="#e9edf3"/><text x="3" y="${yy+4}" fill="#758196" font-size="10">${money(val)}</text>`}).join('');
    const step=Math.max(1,Math.floor((points.length-1)/6)); const labels=points.filter((_,i)=>i%step===0).map((p)=>{const i=points.indexOf(p);return `<text x="${x(i)}" y="250" fill="#758196" font-size="9" text-anchor="middle">${dateText(p.date)}</text>`}).join('');
    const reserveY=y(Number(reserve));
