    const cards=$$('#dashboard .metric'); if(cards.length>=4){
      cards[0].querySelector('strong').textContent=money(f.opening_cash); cards[0].querySelector('em').textContent=`Available cash · as of ${dateText(f.as_of)}`;
      cards[1].querySelector('strong').textContent=money(f.expected_inflows); cards[1].querySelector('em').textContent=`Expected over next ${f.horizon_days} days`;
      cards[2].querySelector('strong').textContent=money(f.expected_outflows); cards[2].querySelector('em').textContent=`Scheduled over next ${f.horizon_days} days`;
      const short=cards[3],breached=Boolean(f.reserve_breach_date),reserveGap=Number(state.reserve)-Number(f.minimum_balance),buffer=Number(f.minimum_balance)-Number(state.reserve);short.classList.toggle('danger',breached);short.classList.toggle('safe',!breached);const shortLabel=short.querySelector('small'),shortValue=short.querySelector('strong'),shortNote=short.querySelector('em');if(shortLabel)shortLabel.textContent=breached?'Projected Shortfall':'Reserve Safety';if(shortValue)shortValue.textContent=breached?`${money(reserveGap)} below reserve`:`${money(buffer)} above reserve`;if(shortNote)shortNote.textContent=breached?`Reserve crossed ${dateText(f.reserve_breach_date)} · lowest ${money(f.minimum_balance)}`:`Lowest balance ${dateText(f.minimum_balance_date)} · reserve ${money(state.reserve)}`;
    }
