    const d=document.createElement('dialog');d.className='ls-dialog';d.innerHTML=`<form class="ls-form"><h2>Forecast date range</h2><p>Choose the dates used to calculate every forecast view. The forecast starts with your saved opening cash on the selected start date.</p><label for="lsForecastStart">Start date</label><input id="lsForecastStart" type="date" required value="${start}"><label for="lsForecastEnd">End date</label><input id="lsForecastEnd" type="date" required value="${end}"><small id="lsForecastRangeHint" style="color:#758196">Select a range from 1 to 90 days.</small><div class="form-actions"><button class="secondary" type="button" data-close>Cancel</button><button class="primary" type="submit">Apply date range</button></div></form>`;
    document.body.append(d);d.showModal();d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove(),{once:true});const startInput=d.querySelector('#lsForecastStart'),endInput=d.querySelector('#lsForecastEnd'),hint=d.querySelector('#lsForecastRangeHint');const showDays=()=>{if(!startInput.value||!endInput.value)return;const days=(Date.parse(`${endInput.value}T00:00:00Z`)-Date.parse(`${startInput.value}T00:00:00Z`))/86400000;hint.textContent=days>=1&&days<=90?`${days} forecast days.`:'Choose an end date 1–90 days after the start date.';hint.style.color=days>=1&&days<=90?'#758196':'#cf5860'};startInput.addEventListener('change',showDays);endInput.addEventListener('change',showDays);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const days=(Date.parse(`${endInput.value}T00:00:00Z`)-Date.parse(`${startInput.value}T00:00:00Z`))/86400000;if(!Number.isInteger(days)||days<1||days>90){showDays();return;}try{await api('/api/forecast-window',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({start_date:startInput.value,horizon_days:days})});state.forecastStart=startInput.value;state.horizon=days;const select=$$('#forecast .scenario-bar select')[1];if(select){let option=[...select.options].find(o=>Number(o.value)===days);if(!option){option=new Option(`Custom range (${days} days)`,String(days));select.add(option)}select.value=String(days)}d.close();await refresh();toast('Forecast date range saved and recalculated.')}catch(err){toast(`Could not update date range: ${err.message}`)}};
